// === Tab: mySketch ===
//experimenting sampling some of the sky into the sea, 
//to try to unify otherwise-unrelated random colour picks.
//AI? no.  Practicing with p5.strands and its noise snippet.

let colours;
let myShader;

function setup() {
	createCanvas(200, windowHeight, WEBGL);
	randomiseColours();
	myShader = buildFilterShader(prepShader);
	setInterval(randomiseColours, 10000)
	select("body").style("background-color", "#202020");
}

function draw() {
	filter(myShader);
}

function prepShader() {
	noiseDetail(6);
	let c1 =
		uniformVec3(() => colours[0]);
	let c2 =
		uniformVec3(() => colours[1]);
	let c3 =
		uniformVec3(() => colours[2]);
	let c4 =
		uniformVec3(() => colours[3]);

	filterColor.begin();
	let crd = filterColor.texCoord;

	//compress towards horizon
	let y2 = sqrt(sqrt(abs(0.5 - crd.y)));
	let skySpeed = 0.01;
	let seaSpeed = 0.04;
	let whiteningY = 1 * (1 - pow(y2, 1 / 4));

	let nSky = noise(1000 + crd.x * 0.2, 1100 + 2 * y2, 100 + skySpeed * 0.001 * millis());
	let colourSky = vec4(mix(c1, c2, nSky), 1);

	if (crd.y < 0.5) {
		//top half of image - sky
		colourSky += whiteningY;
		filterColor.set(colourSky);
	} else {
		//lower half of image - water
		let nSea = noise(crd.x * 0.1, 2 * y2, seaSpeed * 0.001 * millis());
		//two more unrelated colours! a recipe for disaster
		let colour = vec4(mix(c3, c4, nSea), 1);

		// colour = colour, whiteningY,
		colour += whiteningY;
		//how much sky colour to bring in
		const baseReflectionAmount = 0.5;
		let noisedReflectionAmount = baseReflectionAmount * noise(333 + crd.x * 0.1, 557 + y2, seaSpeed * 0.002 * millis())
		colour = mix(colour, colourSky, noisedReflectionAmount);
		filterColor.set(colour);
	}
	filterColor.end();
}

function randomiseColours() {
	colours = [];
	const colourChoices = [
		color(...[0.4, 0.0, 0.4].map(v => v * 255)),
		color(...[0.2, 0.4, 0.3].map(v => v * 255)),
		color(...[0.0, 0.4, 0.6].map(v => v * 255)),
		color("cyan"),
		color("hotpink"),
		color("indigo"),
		color("yellow"),
		color("orange"),
		color("skyblue"),
		color("dodgerblue"),
		color("rgb(26,26,26)")
	];

	colours = shuffle(colourChoices).slice(0, 4).map(convertColourToVec3)
}

//take a p5.Color and convert to [f,f,f] where f is 0.0 - 1.0
function convertColourToVec3(c) {
	return [red(window.color(c)) / 255, green(window.color(c)) / 255, blue(window.color(c)) / 255]
}

function keyPressed() {
	if (key === "s") {
		save("seascape");
	}
}

function mousePressed() {
	if (mouseButton.left) {
		randomiseColours();
	}
}
